// SPEC-P-ms-formats 5.1: the ods-editor-v5 worker.  The v4 worker plus a closed list
// (tests/ods-v5-worker-delta.json): the open reply's format, the xlsx gates, this comment.
//
// SPEC-P-calc-undo 4.2: the ods-editor-v4 worker.  Derived from the frozen

...(typeof event.inputSuffix === "string" ? { inputSuffix: event.inputSuffix } : {}),
// SPEC-P-ms-formats E5: named, and only when the engine sent it.
...(typeof event.format === "string" ? { format: event.format } : {}),

// SPEC-P-ms-formats E4: a .xlsx name opens, and xlsx saves, only where the
// manifest says so; everything else keeps its row.  Both compare the
// value the dispatch sends (String(...)), so an array cannot slip past (Codex review 2026-11-03).
const requiredCapability = request.operation === "save" && payload.format === "ods"
  ? "save-ods"
  : request.operation === "open" && /\.xlsx$/i.test(String(payload.name || "")) ? "open-xlsx"
  : request.operation === "save" && String(payload.format || "") === "xlsx" ? "save-xlsx"
  : OPERATION_CAPABILITIES.get(request.operation);
